  4%, 11%         { transform: translateY(0);     opacity: 1; }
  17%, 24%        { transform: translateY(60px);  opacity: 1; }
  30%, 93%        { transform: translateY(120px); opacity: 1; }
  97%, 100%       { transform: translateY(120px); opacity: 0; }
}
@keyframes chainScan {
  0%, 3%          { opacity: .45; }
